import sys

data = sys.stdin.read().split()
a = data[0]
b = data[1]
ns = len(a)
mp = len(b)
dp = [[False] * (mp + 1) for _ in range(ns + 1)]
dp[0][0] = True
for j in range(1, mp + 1):
    if b[j - 1] == "*":
        dp[0][j] = dp[0][j - 1]
for i in range(1, ns + 1):
    for j in range(1, mp + 1):
        pc = b[j - 1]
        if pc == "*":
            dp[i][j] = dp[i][j - 1] or dp[i - 1][j]
        elif pc == "?" or pc == a[i - 1]:
            dp[i][j] = dp[i - 1][j - 1]
print("YES" if dp[ns][mp] else "NO")

